# input 7 coordinates and output seven coordinates have already been transcribed.
# See whether split subsets undergo uniform translation (candidate dx/dy).
def translation_match(src,dst):
    opts=[]
    for dr in range(-17,18):
      for dc in range(-17,18):
        moved={(r+dr,c+dc) for r,c in src}
        inter=moved&dst
        if inter: opts.append((len(inter),dr,dc,len(src),len(dst)))
    return sorted(opts,reverse=True)[:12]
