 'BL': {(r,c) for r,c in test7 if r>8 and c<8},
 'BR': {(r,c) for r,c in test7 if r>8 and c>8},
}
out7=set(fixed)
for name,pts in parts.items():
    if not pts:continue
    rs=[r for r,c in pts]; cs=[c for r,c in pts]
    dr=(-min(rs) if name[0]=='T' else H-1-max(rs))
    dc=(-min(cs) if name[1]=='L' else W-1-max(cs))
    moved={(r+dr,c+dc) for r,c in pts}
    print(name, len(pts), (dr,dc), sorted(moved))
    out7 |= moved
print('output 7 count',len(out7),'overlap?', sum(len(p) for p in [fixed]+[set()]) if False else '')
# Rays: from top marker down through deepest fixed 7 in column 8; from right marker left through leftmost fixed 7 in row 8.
out2={(r,8) for r in range(max(r for r,c in fixed if c==8)+1)}
out2 |= {(8,c) for c in range(min(c for r,c in fixed if r==8),W)}
out2 -= out7
